using System;using System.IO;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using Staff.Subway;
public static class SunsetContrastSetup {
 [MenuItem("STAFF/Subway/Apply Sunset And Contrast Tuning")]
 public static void Install(){if(EditorApplication.isPlaying)throw new Exception("Exit Play mode first.");var sky=UnityEngine.Object.FindFirstObjectByType<SubwayTimeOfDay>();if(!sky)throw new Exception("Open subway scene.");Directory.CreateDirectory("Library/StaffSubway");EditorSceneManager.SaveScene(sky.gameObject.scene,"Library/StaffSubway/before-sunset-contrast.unity",true);Undo.RecordObjects(new UnityEngine.Object[]{sky,sky.atmosphere},"Sunset contrast tuning");sky.atmosphere.middleOzone=10;sky.atmosphere.noonOzone=45;sky.skyWeather.cloudMotionMultiplier=4;sky.skyWeather.starRevolutionSeconds=1800;sky.skyWeather.cloudColors.sunsetLight=new Color(1,.3f,.2f);sky.skyWeather.cloudColors.sunsetShadow=new Color(.63f,.27f,.4f);sky.atmosphere.Tick(true);sky.ApplySolarDay();sky.ApplySky();EditorUtility.SetDirty(sky);EditorUtility.SetDirty(sky.atmosphere);EditorSceneManager.MarkSceneDirty(sky.gameObject.scene);EditorSceneManager.SaveScene(sky.gameObject.scene);Debug.Log("Sunset contrast saved: ozone 20/10 60/45, clouds 4x, stars 1800 sec, redder sunset.");}
}
